"""Seventh curated tranche of materially distinct Python algorithms."""

ADVANCED_TASK_CODE_SPECS_7 = (
    ("lazy_segment_range_sums", "Write a Python function that processes inclusive range-add and range-sum operations using a lazy-propagation segment tree without mutating the initial sequence.", "def process_range_add_sum(values, operations):\n    size = len(values)\n    tree = [0] * max(1, size * 4)\n    lazy = [0] * max(1, size * 4)\n    def build(node, left, right):\n        if left == right:\n            tree[node] = values[left]\n            return\n        middle = (left + right) // 2\n        build(node * 2, left, middle)\n        build(node * 2 + 1, middle + 1, right)\n        tree[node] = tree[node * 2] + tree[node * 2 + 1]\n    def push(node, left, right):\n        if lazy[node] and left != right:\n            middle = (left + right) // 2\n            for child, width in ((node * 2, middle - left + 1), (node * 2 + 1, right - middle)):\n                tree[child] += lazy[node] * width\n                lazy[child] += lazy[node]\n        lazy[node] = 0\n    def update(node, left, right, start, end, amount):\n        if start <= left and right <= end:\n            tree[node] += amount * (right - left + 1)\n            lazy[node] += amount\n            return\n        push(node, left, right)\n        middle = (left + right) // 2\n        if start <= middle:\n            update(node * 2, left, middle, start, end, amount)\n        if end > middle:\n            update(node * 2 + 1, middle + 1, right, start, end, amount)\n        tree[node] = tree[node * 2] + tree[node * 2 + 1]\n    def query(node, left, right, start, end):\n        if start <= left and right <= end:\n            return tree[node]\n        push(node, left, right)\n        middle = (left + right) // 2\n        total = 0\n        if start <= middle:\n            total += query(node * 2, left, middle, start, end)\n        if end > middle:\n            total += query(node * 2 + 1, middle + 1, right, start, end)\n        return total\n    if size:\n        build(1, 0, size - 1)\n    answers = []\n    for operation in operations:\n        if size == 0 or not 0 <= operation[1] <= operation[2] < size:\n            raise ValueError(\"invalid range\")\n        if operation[0] == \"add\":\n            update(1, 0, size - 1, operation[1], operation[2], operation[3])\n        elif operation[0] == \"sum\":\n            answers.append(query(1, 0, size - 1, operation[1], operation[2]))\n        else:\n            raise ValueError(\"unknown operation\")\n    return answers"),
    ("centered_interval_queries", "Write a Python function that builds a centered interval index and returns all closed intervals containing each query point.", "def intervals_containing_points(intervals, points):\n    checked = []\n    for start, end in intervals:\n        if start > end:\n            raise ValueError(\"interval start exceeds end\")\n        checked.append((start, end))\n    def build(items):\n        if not items:\n            return None\n        endpoints = sorted(value for interval in items for value in interval)\n        center = endpoints[len(endpoints) // 2]\n        left, crossing, right = [], [], []\n        for interval in items:\n            if interval[1] < center:\n                left.append(interval)\n            elif interval[0] > center:\n                right.append(interval)\n            else:\n                crossing.append(interval)\n        return (center, crossing, build(left), build(right))\n    root = build(checked)\n    def search(node, point, result):\n        if node is None:\n            return\n        center, crossing, left, right = node\n        result.extend(interval for interval in crossing if interval[0] <= point <= interval[1])\n        search(left if point < center else right, point, result)\n    answers = []\n    for point in points:\n        matches = []\n        search(root, point, matches)\n        answers.append(sorted(matches))\n    return answers"),
    ("kd_tree_nearest", "Write a Python function that returns the nearest point to each query in two dimensions by constructing and pruning a balanced k-d tree.", "def kd_tree_nearest_points(points, queries):\n    if not points:\n        raise ValueError(\"points must be non-empty\")\n    if any(len(point) != 2 for point in points) or any(len(query) != 2 for query in queries):\n        raise ValueError(\"points must be two-dimensional\")\n    def build(items, depth=0):\n        if not items:\n            return None\n        axis = depth % 2\n        ordered = sorted(items, key=lambda point: (point[axis], point[1 - axis]))\n        middle = len(ordered) // 2\n        return (ordered[middle], axis, build(ordered[:middle], depth + 1), build(ordered[middle + 1:], depth + 1))\n    root = build(list(points))\n    def nearest(node, query, best):\n        if node is None:\n            return best\n        point, axis, left, right = node\n        distance = (point[0] - query[0]) ** 2 + (point[1] - query[1]) ** 2\n        if best is None or (distance, point) < best:\n            best = (distance, point)\n        difference = query[axis] - point[axis]\n        near, far = (left, right) if difference < 0 else (right, left)\n        best = nearest(near, query, best)\n        if difference * difference <= best[0]:\n            best = nearest(far, query, best)\n        return best\n    return [nearest(root, query, None)[1] for query in queries]"),
    ("quadtree_encoding", "Write a Python function that encodes a non-empty square binary grid whose side is a power of two as a recursively nested quadtree, collapsing uniform regions.", "def encode_binary_quadtree(grid):\n    size = len(grid)\n    if size == 0 or size & (size - 1) or any(len(row) != size for row in grid) or any(value not in (0, 1) for row in grid for value in row):\n        raise ValueError(\"grid must be square, binary, and power-of-two sized\")\n    def encode(top, left, width):\n        first = grid[top][left]\n        if all(grid[row][column] == first for row in range(top, top + width) for column in range(left, left + width)):\n            return first\n        half = width // 2\n        return (encode(top, left, half), encode(top, left + half, half), encode(top + half, left, half), encode(top + half, left + half, half))\n    return encode(0, 0, size)"),
    ("burrows_wheeler_transform", "Write a Python function that computes the Burrows-Wheeler transform of a string and the original row index without requiring a sentinel character.", "def burrows_wheeler_transform(text):\n    if not text:\n        return \"\", 0\n    rotations = sorted((text[index:] + text[:index], index) for index in range(len(text)))\n    transformed = \"\".join(rotation[-1] for rotation, _ in rotations)\n    original_index = next(position for position, (_, start) in enumerate(rotations) if start == 0)\n    return transformed, original_index"),
    ("lzw_compression", "Write a Python function that compresses a sequence of byte values into integer codes using Lempel-Ziv-Welch dictionary growth.", "def lzw_compress_bytes(values):\n    if any(not isinstance(value, int) or not 0 <= value <= 255 for value in values):\n        raise ValueError(\"values must be bytes\")\n    dictionary = {(value,): value for value in range(256)}\n    next_code = 256\n    current = ()\n    output = []\n    for value in values:\n        candidate = current + (value,)\n        if candidate in dictionary:\n            current = candidate\n        else:\n            output.append(dictionary[current])\n            dictionary[candidate] = next_code\n            next_code += 1\n            current = (value,)\n    if current:\n        output.append(dictionary[current])\n    return output"),
    ("crc32_checksum", "Write a Python function that computes the standard reflected CRC-32 checksum of byte values using the polynomial 0xEDB88320.", "def crc32_checksum(values):\n    checksum = 0xFFFFFFFF\n    for value in values:\n        if not isinstance(value, int) or not 0 <= value <= 255:\n            raise ValueError(\"values must be bytes\")\n        checksum ^= value\n        for _ in range(8):\n            checksum = (checksum >> 1) ^ (0xEDB88320 if checksum & 1 else 0)\n    return checksum ^ 0xFFFFFFFF"),
    ("unsigned_varint_round_trip", "Write a Python function that encodes nonnegative integers as base-128 varints and decodes the resulting byte stream back to the original values.", "def round_trip_unsigned_varints(values):\n    encoded = []\n    for value in values:\n        if not isinstance(value, int) or value < 0:\n            raise ValueError(\"values must be nonnegative integers\")\n        remaining = value\n        while remaining >= 128:\n            encoded.append((remaining & 127) | 128)\n            remaining >>= 7\n        encoded.append(remaining)\n    decoded = []\n    value = shift = 0\n    for byte in encoded:\n        value |= (byte & 127) << shift\n        if byte & 128:\n            shift += 7\n        else:\n            decoded.append(value)\n            value = shift = 0\n    if shift:\n        raise ValueError(\"truncated varint\")\n    return encoded, decoded"),
    ("json_pointer_lookup", "Write a Python function that resolves RFC 6901-style JSON Pointer paths through nested dictionaries and lists, including escaped slash and tilde tokens.", "def resolve_json_pointer(document, pointer):\n    if pointer == \"\":\n        return document\n    if not pointer.startswith(\"/\"):\n        raise ValueError(\"pointer must be empty or begin with a slash\")\n    current = document\n    for raw_token in pointer[1:].split(\"/\"):\n        token = raw_token.replace(\"~1\", \"/\").replace(\"~0\", \"~\")\n        if isinstance(current, dict):\n            current = current[token]\n        elif isinstance(current, list):\n            if token == \"-\" or not token.isdigit():\n                raise ValueError(\"invalid list index\")\n            current = current[int(token)]\n        else:\n            raise ValueError(\"pointer continues through a scalar\")\n    return current"),
    ("deep_mapping_merge", "Write a Python function that recursively merges two nested dictionaries into a new structure, replacing non-dictionary conflicts with right-side values.", "def deep_merge_mappings(left, right):\n    def copy_value(value):\n        if isinstance(value, dict):\n            return {key: copy_value(item) for key, item in value.items()}\n        if isinstance(value, list):\n            return [copy_value(item) for item in value]\n        return value\n    result = {key: copy_value(value) for key, value in left.items()}\n    for key, value in right.items():\n        if key in result and isinstance(result[key], dict) and isinstance(value, dict):\n            result[key] = deep_merge_mappings(result[key], value)\n        else:\n            result[key] = copy_value(value)\n    return result"),
    ("event_sessionization", "Write a Python function that groups timestamped events by key into sessions separated by more than a supplied nonnegative inactivity gap.", "def sessionize_events(events, inactivity_gap):\n    if inactivity_gap < 0:\n        raise ValueError(\"inactivity gap must be nonnegative\")\n    grouped = {}\n    for event in events:\n        grouped.setdefault(event[\"key\"], []).append(dict(event))\n    sessions = []\n    for key, records in grouped.items():\n        records.sort(key=lambda record: record[\"timestamp\"])\n        current = []\n        previous = None\n        for record in records:\n            if previous is not None and record[\"timestamp\"] - previous > inactivity_gap:\n                sessions.append({\"key\": key, \"events\": current})\n                current = []\n            current.append(record)\n            previous = record[\"timestamp\"]\n        if current:\n            sessions.append({\"key\": key, \"events\": current})\n    sessions.sort(key=lambda session: (session[\"events\"][0][\"timestamp\"], session[\"key\"]))\n    return sessions"),
    ("asof_join", "Write a Python function that left-joins timestamped records to the latest same-key reference record at or before each timestamp.", "def backward_asof_join(records, references):\n    by_key = {}\n    for reference in references:\n        by_key.setdefault(reference[\"key\"], []).append(dict(reference))\n    for values in by_key.values():\n        values.sort(key=lambda record: record[\"timestamp\"])\n    result = []\n    for record in records:\n        candidates = by_key.get(record[\"key\"], [])\n        left, right = 0, len(candidates)\n        while left < right:\n            middle = (left + right) // 2\n            if candidates[middle][\"timestamp\"] <= record[\"timestamp\"]:\n                left = middle + 1\n            else:\n                right = middle\n        result.append({\"record\": dict(record), \"reference\": None if left == 0 else dict(candidates[left - 1])})\n    return result"),
    ("fixed_bucket_resampling", "Write a Python function that sums timestamped numeric observations into fixed-width half-open buckets and emits empty buckets between the observed endpoints.", "def resample_fixed_buckets(observations, width):\n    if width <= 0:\n        raise ValueError(\"width must be positive\")\n    if not observations:\n        return []\n    totals = {}\n    for timestamp, value in observations:\n        bucket = timestamp // width * width\n        totals[bucket] = totals.get(bucket, 0) + value\n    start, end = min(totals), max(totals)\n    return [(bucket, totals.get(bucket, 0)) for bucket in range(start, end + width, width)]"),
    ("fifo_page_faults", "Write a Python function that simulates positive-capacity first-in-first-out page replacement and returns both the fault count and final frame order.", "def simulate_fifo_page_replacement(references, capacity):\n    if capacity <= 0:\n        raise ValueError(\"capacity must be positive\")\n    frames = []\n    present = set()\n    faults = 0\n    for page in references:\n        if page in present:\n            continue\n        faults += 1\n        if len(frames) == capacity:\n            present.remove(frames.pop(0))\n        frames.append(page)\n        present.add(page)\n    return faults, frames"),
    ("banker_safe_sequence", "Write a Python function that returns one safe process-completion order under Banker's algorithm from allocation, maximum-demand, and available-resource matrices, or None when unsafe.", "def banker_safe_sequence(allocation, maximum, available):\n    if len(allocation) != len(maximum) or any(len(row) != len(available) for row in allocation + maximum):\n        raise ValueError(\"resource dimensions do not align\")\n    need = []\n    for held, limit in zip(allocation, maximum):\n        row = [limit[index] - held[index] for index in range(len(available))]\n        if any(value < 0 for value in row):\n            raise ValueError(\"allocation exceeds maximum\")\n        need.append(row)\n    work = list(available)\n    unfinished = set(range(len(allocation)))\n    order = []\n    while unfinished:\n        process = next((candidate for candidate in sorted(unfinished) if all(need[candidate][resource] <= work[resource] for resource in range(len(work)))), None)\n        if process is None:\n            return None\n        for resource, amount in enumerate(allocation[process]):\n            work[resource] += amount\n        unfinished.remove(process)\n        order.append(process)\n    return order"),
    ("ordinary_linear_regression", "Write a Python function that computes slope, intercept, and coefficient of determination for paired numeric observations using ordinary least squares.", "def simple_linear_regression(inputs, outputs):\n    if len(inputs) != len(outputs) or len(inputs) < 2:\n        raise ValueError(\"inputs and outputs must align and contain at least two observations\")\n    input_mean = sum(inputs) / len(inputs)\n    output_mean = sum(outputs) / len(outputs)\n    input_variation = sum((value - input_mean) ** 2 for value in inputs)\n    if input_variation == 0:\n        raise ValueError(\"inputs must vary\")\n    slope = sum((left - input_mean) * (right - output_mean) for left, right in zip(inputs, outputs)) / input_variation\n    intercept = output_mean - slope * input_mean\n    predictions = [intercept + slope * value for value in inputs]\n    residual = sum((actual - predicted) ** 2 for actual, predicted in zip(outputs, predictions))\n    total = sum((actual - output_mean) ** 2 for actual in outputs)\n    determination = 1.0 if total == 0 and residual == 0 else 0.0 if total == 0 else 1 - residual / total\n    return slope, intercept, determination"),
    ("sample_covariance_matrix", "Write a Python function that computes a sample covariance matrix from equal-width observation rows, requiring at least two observations.", "def sample_covariance_matrix(observations):\n    if len(observations) < 2:\n        raise ValueError(\"at least two observations are required\")\n    width = len(observations[0])\n    if any(len(row) != width for row in observations):\n        raise ValueError(\"observations must have equal width\")\n    means = [sum(row[column] for row in observations) / len(observations) for column in range(width)]\n    return [[sum((row[left] - means[left]) * (row[right] - means[right]) for row in observations) / (len(observations) - 1) for right in range(width)] for left in range(width)]"),
    ("kmeans_iterations", "Write a Python function that runs a fixed number of deterministic k-means iterations from supplied equal-dimensional centroids and returns final assignments and centroids.", "def run_kmeans_iterations(points, centroids, iterations):\n    if iterations < 0 or not centroids:\n        raise ValueError(\"iterations must be nonnegative and centroids non-empty\")\n    width = len(centroids[0])\n    if any(len(point) != width for point in points) or any(len(center) != width for center in centroids):\n        raise ValueError(\"dimensions do not align\")\n    centers = [list(center) for center in centroids]\n    assignments = []\n    for _ in range(iterations):\n        assignments = [min(range(len(centers)), key=lambda index: (sum((value - centers[index][axis]) ** 2 for axis, value in enumerate(point)), index)) for point in points]\n        groups = [[] for _ in centers]\n        for point, assignment in zip(points, assignments):\n            groups[assignment].append(point)\n        centers = [[sum(point[axis] for point in group) / len(group) for axis in range(width)] if group else centers[index] for index, group in enumerate(groups)]\n    if iterations == 0:\n        assignments = [min(range(len(centers)), key=lambda index: (sum((value - centers[index][axis]) ** 2 for axis, value in enumerate(point)), index)) for point in points]\n    return assignments, centers"),
    ("dbscan_clusters", "Write a Python function that labels fixed-dimensional points with DBSCAN cluster identifiers or -1 for noise using squared Euclidean distance.", "def dbscan_cluster_labels(points, radius, minimum_points):\n    if radius < 0 or minimum_points <= 0 or (points and any(len(point) != len(points[0]) for point in points)):\n        raise ValueError(\"invalid radius, minimum, or dimensions\")\n    def neighbors(index):\n        return [candidate for candidate, point in enumerate(points) if sum((left - right) ** 2 for left, right in zip(points[index], point)) <= radius * radius]\n    unvisited = None\n    labels = [unvisited] * len(points)\n    cluster = 0\n    for index in range(len(points)):\n        if labels[index] is not unvisited:\n            continue\n        nearby = neighbors(index)\n        if len(nearby) < minimum_points:\n            labels[index] = -1\n            continue\n        labels[index] = cluster\n        queue = list(nearby)\n        position = 0\n        while position < len(queue):\n            candidate = queue[position]\n            position += 1\n            if labels[candidate] == -1:\n                labels[candidate] = cluster\n            if labels[candidate] is not unvisited:\n                continue\n            labels[candidate] = cluster\n            expanded = neighbors(candidate)\n            if len(expanded) >= minimum_points:\n                queue.extend(item for item in expanded if item not in queue)\n        cluster += 1\n    return labels"),
    ("point_in_polygon", "Write a Python function that classifies whether each two-dimensional query point lies inside or on the boundary of a simple polygon using ray casting.", "def points_inside_polygon(polygon, points):\n    if len(polygon) < 3:\n        raise ValueError(\"polygon needs at least three vertices\")\n    answers = []\n    for point_x, point_y in points:\n        inside = False\n        for index, first in enumerate(polygon):\n            second = polygon[(index + 1) % len(polygon)]\n            cross = (second[0] - first[0]) * (point_y - first[1]) - (second[1] - first[1]) * (point_x - first[0])\n            if cross == 0 and min(first[0], second[0]) <= point_x <= max(first[0], second[0]) and min(first[1], second[1]) <= point_y <= max(first[1], second[1]):\n                inside = True\n                break\n            if (first[1] > point_y) != (second[1] > point_y):\n                intersection = first[0] + (point_y - first[1]) * (second[0] - first[0]) / (second[1] - first[1])\n                if point_x < intersection:\n                    inside = not inside\n        answers.append(inside)\n    return answers"),
    ("line_segment_intersection", "Write a Python function that determines whether each pair of closed two-dimensional line segments intersects, including collinear endpoint overlap.", "def segment_intersection_flags(segment_pairs):\n    def orientation(first, second, third):\n        value = (second[0] - first[0]) * (third[1] - first[1]) - (second[1] - first[1]) * (third[0] - first[0])\n        return 0 if value == 0 else 1 if value > 0 else -1\n    def on_segment(first, point, second):\n        return min(first[0], second[0]) <= point[0] <= max(first[0], second[0]) and min(first[1], second[1]) <= point[1] <= max(first[1], second[1])\n    result = []\n    for (first, second), (third, fourth) in segment_pairs:\n        values = (orientation(first, second, third), orientation(first, second, fourth), orientation(third, fourth, first), orientation(third, fourth, second))\n        intersects = values[0] != values[1] and values[2] != values[3]\n        intersects = intersects or values[0] == 0 and on_segment(first, third, second)\n        intersects = intersects or values[1] == 0 and on_segment(first, fourth, second)\n        intersects = intersects or values[2] == 0 and on_segment(third, first, fourth)\n        intersects = intersects or values[3] == 0 and on_segment(third, second, fourth)\n        result.append(intersects)\n    return result"),
    ("polygon_area_centroid", "Write a Python function that returns the signed area and centroid of a nondegenerate simple polygon using cross products.", "def polygon_area_and_centroid(vertices):\n    if len(vertices) < 3:\n        raise ValueError(\"polygon needs at least three vertices\")\n    doubled_area = 0\n    x_total = y_total = 0\n    for index, first in enumerate(vertices):\n        second = vertices[(index + 1) % len(vertices)]\n        cross = first[0] * second[1] - second[0] * first[1]\n        doubled_area += cross\n        x_total += (first[0] + second[0]) * cross\n        y_total += (first[1] + second[1]) * cross\n    if doubled_area == 0:\n        raise ValueError(\"polygon must have nonzero area\")\n    return doubled_area / 2, (x_total / (3 * doubled_area), y_total / (3 * doubled_area))"),
    ("havel_hakimi_graphical", "Write a Python function that decides whether a sequence of nonnegative integers is graphical using the Havel-Hakimi reduction.", "def is_graphical_degree_sequence(degrees):\n    if any(not isinstance(degree, int) or degree < 0 for degree in degrees):\n        raise ValueError(\"degrees must be nonnegative integers\")\n    remaining = list(degrees)\n    while True:\n        remaining = sorted((degree for degree in remaining if degree), reverse=True)\n        if not remaining:\n            return True\n        degree = remaining.pop(0)\n        if degree > len(remaining):\n            return False\n        for index in range(degree):\n            remaining[index] -= 1\n            if remaining[index] < 0:\n                return False"),
    ("prufer_tree_encoding", "Write a Python function that encodes a labeled undirected tree as its Prüfer sequence, validating that the edges form one tree.", "def prufer_encode_tree(edges):\n    if not edges:\n        return []\n    nodes = set()\n    adjacency = {}\n    for left, right in edges:\n        if left == right:\n            raise ValueError(\"self loops are not tree edges\")\n        nodes.update((left, right))\n        adjacency.setdefault(left, set()).add(right)\n        adjacency.setdefault(right, set()).add(left)\n    if len(edges) != len(nodes) - 1:\n        raise ValueError(\"edges do not form a tree\")\n    seen = set()\n    queue = [next(iter(nodes))]\n    for node in queue:\n        if node in seen:\n            continue\n        seen.add(node)\n        queue.extend(adjacency[node] - seen)\n    if seen != nodes:\n        raise ValueError(\"edges do not form a connected tree\")\n    sequence = []\n    for _ in range(len(nodes) - 2):\n        leaf = min(node for node in nodes if len(adjacency[node]) == 1)\n        neighbor = next(iter(adjacency[leaf]))\n        sequence.append(neighbor)\n        adjacency[neighbor].remove(leaf)\n        adjacency[leaf].clear()\n    return sequence"),
)
